sys_script.script:
(function executeRule(current, previous) {

    if (
        !current.received_at_security_desk
            .changesTo(true)
    ) {
        return;
    }


    var type =
        (
            current.getValue('report_type') || ''
        )
        .toString()
        .toLowerCase();


    if (
        type !== 'found'
    ) {
        return;
    }


    var reporterId =
        current.getValue('reporter');


    if (!reporterId) {
        return;
    }


    var service =
        new CampusMatchNotificationService();


    service.createForUser(
        reporterId,
        'student',
        'Found item received at Security Desk',
        'Your reported Found item has been recorded at the Security Desk.',
        '?id=campusmatch_dashboard',
        'custody',
        current.getTableName(),
        current.getUniqueValue(),
        'security_received:' +
            current.getUniqueValue(),
        'CampusMatch - Found Item Security Desk Receipt'
    );

})(
    current,
    previous
);
